mapper.select:
SELECT repots.id as aid,result.id as rid,result.request_serialize,regi.`name`,orgtree.Org_Name,repot.id,repot.result_serialNum,repot.request_serialNum,repot.user_code,repot.qtime,repot.gender,repot.age,result.diseaseId,result.qname,result.qcode,result.qvalue,result.last_value,result.changes,result.optimal,result.remark,repots.diseasId,repots.risk_level,repots.risk_desc,repots.now_risk_desc,repots.now_risk_desc,repots.now_risk_value,repots.now_risk_level,repots.now_risk_last_value,repots.ideal_risk_desc,repots.ideal_risk_level from yh_disease_assess_total_report2 repot LEFT JOIN yh_disease_risk_result result ON repot.request_serialNum =result.request_serialize AND repot.user_code=result.user_code LEFT JOIN yh_disease_assess_report repots ON result.request_serialize=repots.request_serialNum AND result.user_code=repots.user_code LEFT JOIN yh_user_reginfo regi ON regi.user_code=repot.user_code LEFT JOIN yh_org_tree orgtree on regi.Org_Code=orgtree.Org_Code
orgtree.Org_Code like CONCAT('%',#{nowselect},'%')
and repot.qtime between #{begintime} and #{endtime}
